//! Exclusive in-process editing leases. Do not expose actor identities from requests:
//! derive them from the authenticated principal. A lease does not itself recover drafts.
use std::{collections::HashMap,io::Read,sync::{Arc,Mutex,RwLock,Weak},time::{Duration,Instant}};

#[derive(Clone,Debug,PartialEq,Eq)]
pub struct Lease { pub workspace:String, pub note:String, pub actor:String, pub id:String }
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum Error { Busy, AgentAlreadyEditing, Expired, Poisoned, EntropyUnavailable, PendingDraft, DraftCheckFailed }
struct Entry { lease:Lease, deadline:Instant, active:bool }
#[derive(Default)] struct State { entries:HashMap<(String,String),Entry>, gates:HashMap<(String,String),Weak<Mutex<()>>>, workspaces:HashMap<String,Weak<RwLock<()>>> }
#[derive(Default)] pub struct NoteEditLocks { state:Mutex<State> }
impl NoteEditLocks {
 fn workspace_gate(&self,workspace:&str)->Result<Arc<RwLock<()>>,Error>{let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;s.workspaces.retain(|_,gate|gate.strong_count()>0);if let Some(gate)=s.workspaces.get(workspace).and_then(Weak::upgrade){return Ok(gate)}let gate=Arc::new(RwLock::new(()));s.workspaces.insert(workspace.into(),Arc::downgrade(&gate));Ok(gate)}
 /// Caller must revoke permissions first and release any auth gate before calling.
 /// New acquisitions must recheck authorization while holding the note gate.
 pub fn invalidate_actor_bounded(&self,actor:&str,limit:Duration)->Result<bool,Error>{
  let workspaces={let s=self.state.lock().map_err(|_|Error::Poisoned)?;let mut ids=s.entries.values().filter(|e|e.lease.actor==actor).map(|e|e.lease.workspace.clone()).collect::<Vec<_>>();ids.sort();ids.dedup();ids};let until=Instant::now()+limit;
  for workspace in workspaces {let gate=self.workspace_gate(&workspace)?;loop {match gate.try_write(){Ok(_write)=>{let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;s.entries.retain(|(wid,_),e|wid!=&workspace||e.lease.actor!=actor);break},Err(std::sync::TryLockError::Poisoned(_))=>return Err(Error::Poisoned),Err(std::sync::TryLockError::WouldBlock)=>{if Instant::now()>=until{return Ok(false)}std::thread::sleep(Duration::from_millis(10));}}}}
  Ok(true)
 }
 pub fn invalidate_actor(&self,actor:&str)->Result<(),Error>{
  let workspaces={let s=self.state.lock().map_err(|_|Error::Poisoned)?;let mut ids=s.entries.values().filter(|e|e.lease.actor==actor).map(|e|e.lease.workspace.clone()).collect::<Vec<_>>();ids.sort();ids.dedup();ids};
  for workspace in workspaces {let gate=self.workspace_gate(&workspace)?;let _write=gate.write().map_err(|_|Error::Poisoned)?;let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;s.entries.retain(|(wid,_),e|wid!=&workspace||e.lease.actor!=actor);}Ok(())
 }
 /// Serializes destructive changes to selected notes with all lease operations.
 pub fn with_unleased<T>(&self,workspace:&str,notes:&[String],operation:impl FnOnce()->T)->Result<T,Error>{let workspace_gate=self.workspace_gate(workspace)?;let _read=workspace_gate.read().map_err(|_|Error::Poisoned)?;let mut ids=notes.to_vec();ids.sort();ids.dedup();let gates=ids.iter().map(|id|self.gate(workspace,id)).collect::<Result<Vec<_>,_>>()?;let _guards=gates.iter().map(|gate|gate.lock().map_err(|_|Error::Poisoned)).collect::<Result<Vec<_>,_>>()?;{let s=self.state.lock().map_err(|_|Error::Poisoned)?;let now=Instant::now();if ids.iter().any(|id|s.entries.get(&(workspace.to_owned(),id.clone())).is_some_and(|e|e.active||e.deadline>now)){return Err(Error::Busy)}}Ok(operation())}
 /// Hold the workspace gate during a board change and supply currently leased IDs.
 pub fn with_board<T>(&self,workspace:&str,operation:impl FnOnce(&[String])->T)->Result<T,Error>{let gate=self.workspace_gate(workspace)?;let _write=gate.write().map_err(|_|Error::Poisoned)?;let ids={let s=self.state.lock().map_err(|_|Error::Poisoned)?;let now=Instant::now();s.entries.values().filter(|e|e.lease.workspace==workspace&&(e.active||e.deadline>now)).map(|e|e.lease.note.clone()).collect::<Vec<_>>()};Ok(operation(&ids))}
 pub fn close_workspace<T,E>(&self,workspace:&str,close:impl FnOnce()->Result<T,E>)->Result<Result<T,E>,Error>{let gate=self.workspace_gate(workspace)?;let _write=gate.write().map_err(|_|Error::Poisoned)?;let result=close();if result.is_ok(){let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;s.entries.retain(|(wid,_),_|wid!=workspace)}Ok(result)}
 pub fn recover<T>(&self,workspace:&str,operation:impl FnOnce()->T)->Result<T,Error>{let gate=self.workspace_gate(workspace)?;let _write=gate.write().map_err(|_|Error::Poisoned)?;{let s=self.state.lock().map_err(|_|Error::Poisoned)?;let now=Instant::now();if s.entries.values().any(|e|e.lease.workspace==workspace&&(e.active||e.deadline>now)){return Err(Error::Busy)}}Ok(operation())}
 fn gate(&self,workspace:&str,note:&str)->Result<Arc<Mutex<()>>,Error>{let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;s.gates.retain(|_,gate|gate.strong_count()>0);let key=(workspace.into(),note.into());if let Some(gate)=s.gates.get(&key).and_then(Weak::upgrade){return Ok(gate)}let gate=Arc::new(Mutex::new(()));s.gates.insert(key,Arc::downgrade(&gate));Ok(gate)}
 fn random_id()->Result<String,Error>{let mut bytes=[0u8;32];std::fs::File::open("/dev/urandom").and_then(|mut f|f.read_exact(&mut bytes)).map_err(|_|Error::EntropyUnavailable)?;Ok(bytes.iter().map(|b|format!("{b:02x}")).collect())}
 #[cfg(test)] fn acquire(&self,workspace:&str,note:&str,actor:&str,is_agent:bool,ttl:Duration)->Result<Lease,Error>{
  self.acquire_checked(workspace,note,actor,is_agent,ttl,||Ok(false))
 }
 /// The caller must check durable drafts before granting the first new writer.
 pub fn acquire_checked(&self,workspace:&str,note:&str,actor:&str,is_agent:bool,ttl:Duration,has_draft:impl FnOnce()->Result<bool,Error>)->Result<Lease,Error>{self.acquire_checked_with_auth(workspace,note,actor,is_agent,ttl,has_draft,||Ok(()))}
 pub fn acquire_checked_with_auth<G>(&self,workspace:&str,note:&str,actor:&str,is_agent:bool,ttl:Duration,has_draft:impl FnOnce()->Result<bool,Error>,auth:impl FnOnce()->Result<G,Error>)->Result<Lease,Error>{
  let workspace_gate=self.workspace_gate(workspace)?;let _read=workspace_gate.read().map_err(|_|Error::Poisoned)?;let gate=self.gate(workspace,note)?;let _guard=gate.lock().map_err(|_|Error::Poisoned)?;if has_draft()?{return Err(Error::PendingDraft)}let _auth=auth()?;let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;let now=Instant::now();
  // Keep expired entries for other notes while their operation may still be running;
  // a per-note gate prevents a successor from overtaking an active operation.
  s.entries.retain(|_,e|e.active||e.deadline>now);let key=(workspace.to_owned(),note.to_owned());if s.entries.get(&key).is_some_and(|e|e.deadline>now){return Err(Error::Busy)}
  if is_agent&&s.entries.iter().any(|(k,e)|*k!=key&&e.lease.actor==actor&&(e.deadline>now||e.active)){return Err(Error::AgentAlreadyEditing)}
  let deadline=now.checked_add(ttl).filter(|t|*t>now).ok_or(Error::Expired)?;
  let lease=Lease{workspace:key.0.clone(),note:key.1.clone(),actor:actor.to_owned(),id:Self::random_id()?};s.entries.insert(key,Entry{lease:lease.clone(),deadline,active:false});Ok(lease)
 }
 pub fn renew(&self,lease:&Lease,ttl:Duration)->Result<(),Error>{let workspace_gate=self.workspace_gate(&lease.workspace)?;let _read=workspace_gate.read().map_err(|_|Error::Poisoned)?;let gate=self.gate(&lease.workspace,&lease.note)?;let _guard=gate.lock().map_err(|_|Error::Poisoned)?;let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;let now=Instant::now();let e=s.entries.get_mut(&(lease.workspace.clone(),lease.note.clone())).ok_or(Error::Expired)?;if e.lease!=*lease||e.deadline<=now{return Err(Error::Expired)}e.deadline=now.checked_add(ttl).filter(|t|*t>now).ok_or(Error::Expired)?;Ok(())}
 pub fn release(&self,lease:&Lease)->Result<(),Error>{let workspace_gate=self.workspace_gate(&lease.workspace)?;let _read=workspace_gate.read().map_err(|_|Error::Poisoned)?;let gate=self.gate(&lease.workspace,&lease.note)?;let _guard=gate.lock().map_err(|_|Error::Poisoned)?;let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;let key=(lease.workspace.clone(),lease.note.clone());if !s.entries.get(&key).is_some_and(|e|e.lease==*lease&&e.deadline>Instant::now()){return Err(Error::Expired)}s.entries.remove(&key);Ok(())}
 pub fn with_lease<T>(&self,lease:&Lease,operation:impl FnOnce()->T)->Result<T,Error>{let workspace_gate=self.workspace_gate(&lease.workspace)?;let _read=workspace_gate.read().map_err(|_|Error::Poisoned)?;let gate=self.gate(&lease.workspace,&lease.note)?;let _guard=gate.lock().map_err(|_|Error::Poisoned)?;let key=(lease.workspace.clone(),lease.note.clone());{let mut s=self.state.lock().map_err(|_|Error::Poisoned)?;let e=s.entries.get_mut(&key).ok_or(Error::Expired)?;if e.lease!=*lease||e.deadline<=Instant::now(){return Err(Error::Expired)}e.active=true;}let _active=Active{state:&self.state,key};Ok(operation())}
}
struct Active<'a>{state:&'a Mutex<State>,key:(String,String)}
impl Drop for Active<'_>{fn drop(&mut self){if let Ok(mut s)=self.state.lock(){if let Some(e)=s.entries.get_mut(&self.key){e.active=false}}}}
#[cfg(test)] mod tests {
 use super::*;use std::sync::{Arc,Barrier,mpsc};
 #[test] fn exclusivity_and_per_agent_limit(){let l=NoteEditLocks::default();let a=l.acquire("w","a","agent",true,Duration::from_secs(5)).unwrap();assert_eq!(l.acquire("w","a","human",false,Duration::from_secs(5)),Err(Error::Busy));assert_eq!(l.acquire("w","b","agent",true,Duration::from_secs(5)),Err(Error::AgentAlreadyEditing));l.release(&a).unwrap();assert!(l.acquire("w","b","agent",true,Duration::from_secs(5)).is_ok());}
 #[test] fn expired_and_prior_process_leases_cannot_mutate(){let l=NoteEditLocks::default();let a=l.acquire("w","a","a",true,Duration::from_millis(1)).unwrap();std::thread::sleep(Duration::from_millis(5));let b=l.acquire("w","a","b",true,Duration::from_secs(5)).unwrap();assert_ne!(a.id,b.id);assert_eq!(l.with_lease(&a,||42),Err(Error::Expired));assert_eq!(l.release(&a),Err(Error::Expired));let restarted=NoteEditLocks::default();let c=restarted.acquire("w","a","a",true,Duration::from_secs(5)).unwrap();assert_ne!(a.id,c.id);assert_eq!(restarted.with_lease(&a,||42),Err(Error::Expired));}
 #[test] fn simultaneous_acquire_has_one_winner(){let l=Arc::new(NoteEditLocks::default());let barrier=Arc::new(Barrier::new(3));let mut threads=vec![];for actor in ["a","b"] {let l=l.clone();let barrier=barrier.clone();threads.push(std::thread::spawn(move||{barrier.wait();l.acquire("w","n",actor,true,Duration::from_secs(5)).is_ok()}));}barrier.wait();assert_eq!(threads.into_iter().map(|t|t.join().unwrap() as usize).sum::<usize>(),1);}
 #[test] fn slow_note_does_not_block_other_note(){let l=Arc::new(NoteEditLocks::default());let a=l.acquire("w","a","a",true,Duration::from_secs(5)).unwrap();let b=l.acquire("w","b","b",true,Duration::from_secs(5)).unwrap();let (start_tx,start_rx)=mpsc::channel();let (end_tx,end_rx)=mpsc::channel();let copy=l.clone();let worker=std::thread::spawn(move||copy.with_lease(&a,||{start_tx.send(()).unwrap();end_rx.recv().unwrap()}));start_rx.recv().unwrap();assert_eq!(l.with_lease(&b,||42),Ok(42));end_tx.send(()).unwrap();worker.join().unwrap().unwrap();}
 #[test] fn expired_lease_during_active_operation_still_counts_for_agent(){let l=Arc::new(NoteEditLocks::default());let a=l.acquire("w","a","agent",true,Duration::from_millis(40)).unwrap();let (start_tx,start_rx)=mpsc::channel();let (end_tx,end_rx)=mpsc::channel();let copy=l.clone();let worker=std::thread::spawn(move||copy.with_lease(&a,||{start_tx.send(()).unwrap();end_rx.recv().unwrap()}));start_rx.recv().unwrap();std::thread::sleep(Duration::from_millis(70));assert_eq!(l.acquire("w","b","agent",true,Duration::from_secs(2)),Err(Error::AgentAlreadyEditing));end_tx.send(()).unwrap();worker.join().unwrap().unwrap();assert!(l.acquire("w","b","agent",true,Duration::from_secs(2)).is_ok());}

 #[test] fn pending_or_unreadable_draft_denies_new_writer(){let l=NoteEditLocks::default();assert_eq!(l.acquire_checked("w","n","a",true,Duration::from_secs(1),||Ok(true)),Err(Error::PendingDraft));assert_eq!(l.acquire_checked("w","n","a",true,Duration::from_secs(1),||Err(Error::DraftCheckFailed)),Err(Error::DraftCheckFailed));assert!(l.acquire_checked("w","n","a",true,Duration::from_secs(1),||Ok(false)).is_ok());}

 #[test] fn pending_draft_prevents_successor_after_expired_active_edit(){use std::sync::atomic::{AtomicBool,Ordering};let l=Arc::new(NoteEditLocks::default());let draft=Arc::new(AtomicBool::new(false));let a=l.acquire_checked("w","n","a",true,Duration::from_millis(30),||Ok(false)).unwrap();let (tx,rx)=mpsc::channel();let copy=l.clone();let d=draft.clone();let writer=std::thread::spawn(move||copy.with_lease(&a,||{tx.send(()).unwrap();std::thread::sleep(Duration::from_millis(80));d.store(true,Ordering::SeqCst)}));rx.recv().unwrap();std::thread::sleep(Duration::from_millis(40));let result=l.acquire_checked("w","n","b",true,Duration::from_secs(1),||Ok(draft.load(Ordering::SeqCst)));writer.join().unwrap().unwrap();assert_eq!(result,Err(Error::PendingDraft));}

 #[test] fn recovery_rejected_until_active_lease_released(){let l=NoteEditLocks::default();let a=l.acquire("w","n","a",true,Duration::from_secs(2)).unwrap();assert_eq!(l.recover("w",||42),Err(Error::Busy));assert_eq!(l.recover("other",||42),Ok(42));l.release(&a).unwrap();assert_eq!(l.recover("w",||42),Ok(42));}

 #[test] fn close_invalidates_only_closed_workspace(){let l=NoteEditLocks::default();let a=l.acquire("w","n","a",true,Duration::from_secs(2)).unwrap();let b=l.acquire("other","n","b",true,Duration::from_secs(2)).unwrap();assert_eq!(l.close_workspace("w",||Ok::<_,()>(())),Ok(Ok(())));assert_eq!(l.with_lease(&a,||1),Err(Error::Expired));assert_eq!(l.with_lease(&b,||1),Ok(1));assert!(l.acquire("w","n","a",true,Duration::from_secs(2)).is_ok());}

 #[test] fn close_waits_for_active_mutation_before_invalidating(){let l=Arc::new(NoteEditLocks::default());let a=l.acquire("w","n","a",true,Duration::from_secs(2)).unwrap();let (started,ready)=mpsc::channel();let (finish,wait)=mpsc::channel();let edit=l.clone();let worker=std::thread::spawn(move||edit.with_lease(&a,||{started.send(()).unwrap();wait.recv().unwrap()}));ready.recv().unwrap();let (closed_tx,closed_rx)=mpsc::channel();let close=l.clone();let closer=std::thread::spawn(move||{let result=close.close_workspace("w",||Ok::<_,()>(()));closed_tx.send(result).unwrap()});assert!(closed_rx.recv_timeout(Duration::from_millis(40)).is_err());finish.send(()).unwrap();worker.join().unwrap().unwrap();assert_eq!(closed_rx.recv_timeout(Duration::from_secs(1)).unwrap(),Ok(Ok(())));closer.join().unwrap();}

 #[test] fn revoked_while_draft_check_waits_cannot_acquire(){let locks=std::sync::Arc::new(NoteEditLocks::default());let auth=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));let l=locks.clone();let a=auth.clone();let (started,ready)=std::sync::mpsc::channel();let (go,wait)=std::sync::mpsc::channel();let t=std::thread::spawn(move||l.acquire_checked_with_auth("w","a","agent:a",true,Duration::from_secs(5),||{started.send(()).unwrap();wait.recv().unwrap();Ok(false)},||if a.load(std::sync::atomic::Ordering::SeqCst){Ok(())}else{Err(Error::DraftCheckFailed)}));ready.recv().unwrap();auth.store(false,std::sync::atomic::Ordering::SeqCst);locks.invalidate_actor("agent:a").unwrap();go.send(()).unwrap();assert_eq!(t.join().unwrap(),Err(Error::DraftCheckFailed));}
 #[test] fn invalidation_reports_pending_for_active_commit(){let l=std::sync::Arc::new(NoteEditLocks::default());let lease=l.acquire("w","a","agent:a",true,Duration::from_secs(5)).unwrap();let clone=l.clone();let (started,ready)=std::sync::mpsc::channel();let (go,wait)=std::sync::mpsc::channel();let t=std::thread::spawn(move||clone.with_lease(&lease,||{started.send(()).unwrap();wait.recv().unwrap()}));ready.recv().unwrap();assert_eq!(l.invalidate_actor_bounded("agent:a",Duration::from_millis(20)),Ok(false));go.send(()).unwrap();t.join().unwrap().unwrap();assert_eq!(l.invalidate_actor_bounded("agent:a",Duration::from_secs(1)),Ok(true));}
 #[test] fn revoked_actor_loses_leases_without_disturbing_others(){let l=NoteEditLocks::default();let a=l.acquire("w","a","agent:a",true,Duration::from_secs(5)).unwrap();let b=l.acquire("w","b","agent:b",true,Duration::from_secs(5)).unwrap();l.invalidate_actor("agent:a").unwrap();assert_eq!(l.with_lease(&a,||1),Err(Error::Expired));assert_eq!(l.with_lease(&b,||1),Ok(1));assert!(l.acquire("w","a","human",false,Duration::from_secs(5)).is_ok());}

 #[test] fn destructive_operation_blocks_only_selected_locked_notes(){let l=NoteEditLocks::default();let a=l.acquire("w","a","agent",true,Duration::from_secs(5)).unwrap();assert_eq!(l.with_unleased("w",&["a".into()],||7),Err(Error::Busy));assert_eq!(l.with_unleased("w",&["b".into()],||7),Ok(7));assert_eq!(l.with_unleased("w",&["b".into(),"a".into()],||7),Err(Error::Busy));l.release(&a).unwrap();assert_eq!(l.with_unleased("w",&["a".into()],||7),Ok(7));}

}
